import { BaseException } from '@game-studio/exceptions';
import { Locale } from '../../../types';

export class InvalidValueException extends BaseException {
    public readonly propertyType: string;

    public readonly propertyName?: string;

    public readonly value: string;

    constructor(propertyType: string, value: string, propertyName?: string) {
        const propertyString = propertyName ? ` for ${propertyName}` : '';
        super('InvalidValueException', `"${value}" is not a valid ${propertyType} value${propertyString}`);

        this.propertyType = propertyType;
        this.propertyName = propertyName;
        this.value = value;
    }

    public localise(locale: Locale): void {
        this.buttonText = this.getButtonText(locale);
        this.displayMessage = this.getGenericErrorMessage(locale);
    }
}
